```cpp
#include <iostream>
#include <fstream>
#include <iomanip>
#include <vector>
#include <cstdlib>
using namespace std;

int main() {
    ifstream plik("wielokaty.txt");
    int k;
    plik >> k;
    cout << fixed << setprecision(2);
    double suma = 0;
    int maxIdx = 1;
    double maxPole = 0;
    for (int w = 0; w < k; w++) {
        int n;
        plik >> n;
        vector<int> x(n), y(n);
        for (int i = 0; i < n; i++)
            plik >> x[i] >> y[i];
        int s = 0;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            s += x[i] * y[j] - x[j] * y[i];
        }
        double pole = abs(s) / 2.0;
        cout << "Wielokat " << w + 1 << " (" << n << " wierzch.): pole = " << pole << endl;
        suma += pole;
        if (pole > maxPole) {
            maxPole = pole;
            maxIdx = w + 1;
        }
    }
    cout << "Laczne pole: " << suma << endl;
    cout << "Najwiekszy: wielokat " << maxIdx << endl;
    return 0;
}
```

